// Unity 2022 LTS / Unity 6. Place in Assets/Editor/MoonFullTerrainImporter.cs
// Reads files generated by convert_full_sdem.py, preserving full physical dimensions.
using System;
using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

public static class MoonFullTerrainImporter
{
    [Serializable]
    private class Manifest
    {
        public int manifestVersion;
        public int tileCols;
        public int tileRows;
        public int tileResolution;
        public float tileWidthMeters;
        public float tileLengthMeters;
        public float totalWidthMeters;
        public float totalLengthMeters;
        public float heightRangeMeters;
        public float sourceMinHeightMeters;
        public float sourceMaxHeightMeters;
        public string sourceDataName;
        public int filledNodataPixelCount;
    }

    private const string InputFolder = "Assets/MoonTerrain/InputData";
    private const string OutputFolder = "Assets/MoonTerrain/GeneratedFull";
    private const string RootName = "NASA_NobileRim1_Full";

    [MenuItem("Tools/Moon Terrain/Build FULL SDEM (All Tiles)")]
    public static void Build()
    {
        string rootPath = Path.GetDirectoryName(Application.dataPath);
        string dir = Path.Combine(rootPath, InputFolder);
        string manifestPath = Path.Combine(dir, "manifest.json");
        if (!File.Exists(manifestPath))
        {
            EditorUtility.DisplayDialog("Moon Terrain", "Missing manifest: " + manifestPath, "OK");
            return;
        }
        Manifest m = JsonUtility.FromJson<Manifest>(File.ReadAllText(manifestPath));
        if (m == null || m.manifestVersion != 2 || m.tileCols < 1 || m.tileRows < 1 ||
            m.tileResolution < 33 || m.tileResolution > 4097 ||
            m.tileWidthMeters <= 0 || m.tileLengthMeters <= 0 || m.heightRangeMeters <= 0)
            throw new InvalidDataException("Invalid manifest for full SDEM importer.");

        if (GameObject.Find(RootName) != null || AssetDatabase.IsValidFolder(OutputFolder))
        {
            EditorUtility.DisplayDialog("Moon Terrain", "Existing full-moon import detected. To reimport, remove the previous " +
                RootName + " hierarchy root and delete " + OutputFolder + " in the Project window, then retry.", "OK");
            return;
        }

        // Validate every tile BEFORE creating objects/assets.
        long bytes = (long)m.tileResolution * m.tileResolution * 2;
        for (int r = 0; r < m.tileRows; r++)
            for (int c = 0; c < m.tileCols; c++)
            {
                string file = Path.Combine(dir, FileName(r, c));
                if (!File.Exists(file) || new FileInfo(file).Length != bytes)
                    throw new InvalidDataException("Missing or corrupt RAW: " + file + ". Expected " + bytes + " bytes.");
            }

        if (!EditorUtility.DisplayDialog("Build full Nobile Rim 1 terrain?",
            $"{m.tileCols} x {m.tileRows} tiles, {m.totalWidthMeters / 1000f:F3} x " +
            $"{m.totalLengthMeters / 1000f:F3} km. SDEM NoData filled: {m.filledNodataPixelCount} pixels.\n" +
            "The existing scene remains unchanged until the build starts. Continue?", "Build", "Cancel"))
            return;

        if (!AssetDatabase.IsValidFolder("Assets/MoonTerrain"))
            AssetDatabase.CreateFolder("Assets", "MoonTerrain");
        AssetDatabase.CreateFolder("Assets/MoonTerrain", "GeneratedFull");
        GameObject root = new GameObject(RootName);
        Terrain[,] grid = new Terrain[m.tileRows, m.tileCols];
        int total = m.tileRows * m.tileCols;
        try
        {
            for (int r = 0; r < m.tileRows; r++)
                for (int c = 0; c < m.tileCols; c++)
                {
                    int current = r * m.tileCols + c;
                    EditorUtility.DisplayProgressBar("Importing Nobile Rim 1", $"Tile {current + 1} / {total}", (float)current / total);
                    int n = m.tileResolution;
                    byte[] raw = File.ReadAllBytes(Path.Combine(dir, FileName(r, c)));
                    float[,] heights = new float[n, n];
                    int at = 0;
                    for (int z = 0; z < n; z++)
                        for (int x = 0; x < n; x++)
                        {
                            ushort sample = (ushort)(raw[at] | (raw[at + 1] << 8));
                            heights[z, x] = sample / 65535f;
                            at += 2;
                        }

                    TerrainData data = new TerrainData();
                    data.heightmapResolution = n;
                    data.size = new Vector3(m.tileWidthMeters, m.heightRangeMeters, m.tileLengthMeters);
                    data.SetHeights(0, 0, heights);
                    string name = $"moon_r{r:D2}_c{c:D2}";
                    AssetDatabase.CreateAsset(data, $"{OutputFolder}/{name}.asset");
                    GameObject go = Terrain.CreateTerrainGameObject(data);
                    go.name = name;
                    go.transform.SetParent(root.transform, false);
                    go.transform.position = new Vector3(
                        c * m.tileWidthMeters,
                        0f,
                        (m.tileRows - 1 - r) * m.tileLengthMeters
                    );
                    Terrain t = go.GetComponent<Terrain>();
                    t.groupingID = 1234567;
                    t.allowAutoConnect = false;
                    grid[r, c] = t;
                }

            for (int r = 0; r < m.tileRows; r++)
                for (int c = 0; c < m.tileCols; c++)
                    grid[r, c].SetNeighbors(
                        c > 0 ? grid[r, c - 1] : null,
                        r > 0 ? grid[r - 1, c] : null,
                        c < m.tileCols - 1 ? grid[r, c + 1] : null,
                        r < m.tileRows - 1 ? grid[r + 1, c] : null
                    );
            AssetDatabase.SaveAssets();
            EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());
            Selection.activeGameObject = root;
            Debug.Log($"Nobile Rim 1 FULL: {total} tiles; {m.totalWidthMeters:F2} x " +
                $"{m.totalLengthMeters:F2} m, original Y range {m.heightRangeMeters:F2} m. " +
                "All child Transform scales are (1,1,1). Save scene (Ctrl+S).");
            EditorUtility.DisplayDialog("Import complete", "Created " + total +
                " connected Terrain tiles. Save your scene (Ctrl+S).", "OK");
        }
        finally
        {
            EditorUtility.ClearProgressBar();
        }
    }

    private static string FileName(int row, int col) => $"moon_r{row:D2}_c{col:D2}.raw";
}
